#[local] Abbreviation call_resize := (PECSRD1S.call_resize L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl tl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UNS0 POK TL0 POS0 RSZ FB FBT KONT).
#[local] Abbreviation call_srcread := (PECSRD1S.call_srcread L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl tl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UNS0 POK TL0 POS0 RSZ FB FBT KONT).
#[local] Abbreviation call_filltb := (PECSRD1S.call_filltb L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl tl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UNS0 POK TL0 POS0 RSZ FB FBT KONT).
#[local] Abbreviation unread_nn := (PECSRD1S.unread_nn L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl tl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UNS0 POK TL0 POS0 RSZ FB FBT KONT).
#[local] Abbreviation pos_acct := (PECSRD1S.pos_acct L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl tl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UNS0 POK TL0 POS0 RSZ FB FBT KONT).
#[local] Abbreviation TX_len := (PECSRD1S.TX_len L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl tl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UNS0 POK TL0 POS0 RSZ FB FBT KONT).
#[local] Abbreviation after_read := (PECSRD2S.after_read L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl tl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UNS0 POK TL0 POS0 RSZ FB FBT KONT).
Ltac kept_tac KS KP := intros x Hx; rewrite (KS x) by (revert x Hx; apply PECSRD1S.sub_in; vm_compute; reflexivity); apply KP; exact Hx.

